import { useEffect, useRef } from 'react'
import { View, ActivityIndicator, Platform } from 'react-native'

const LOADER_STYLES = `
:root{--forest:#0D0D0F;--forest-deep:#0A0A0C;--gold:#fec20e;--white:#fff;--mx:0;--my:0}
.ml-loader{position:relative;isolation:isolate;display:flex;width:100%;height:100%;align-items:center;justify-content:center;flex-direction:column;gap:clamp(22px,4.5vh,42px);padding:32px 18px;overflow:hidden;background:radial-gradient(ellipse at 50% 47%,#1A1A1E 0%,var(--forest) 46%,var(--forest-deep) 100%)}
.ml-loader::before,.ml-loader::after{content:"";position:absolute;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(2px)}
.ml-loader::before{width:min(76vw,520px);aspect-ratio:1;background:radial-gradient(circle,rgba(254,194,14,.105),rgba(254,194,14,0) 68%);transform:translate(calc(var(--mx)*10px),calc(var(--my)*10px));transition:transform .25s ease-out}
.ml-loader::after{inset:0;background:linear-gradient(110deg,transparent 15%,rgba(255,255,255,.018) 50%,transparent 85%);opacity:.55}
.ml-logo-stage{position:relative;width:min(76vw,500px);max-width:100%;transform:perspective(900px) rotateX(calc(var(--my)*-1.2deg)) rotateY(calc(var(--mx)*1.2deg));transition:transform .24s ease-out;will-change:transform;filter:drop-shadow(0 12px 22px rgba(13,29,16,.10))}
.ml-brand-svg{display:block;width:100%;height:auto;overflow:visible}
.ml-shape{stroke-linecap:round;stroke-linejoin:round;paint-order:stroke fill}
.ml-emblem-shape{fill:var(--gold);stroke:var(--gold);stroke-width:1;stroke-dasharray:1;stroke-dashoffset:1;fill-opacity:0;animation:mlContourReveal 1.05s cubic-bezier(.65,0,.25,1) .12s forwards;transform-box:fill-box;transform-origin:center}
.ml-script-shape{fill:var(--white);stroke:var(--white);stroke-width:1.15;stroke-dasharray:1;stroke-dashoffset:1;fill-opacity:0;animation:mlContourReveal 1.1s cubic-bezier(.65,0,.25,1) calc(.64s + var(--order)*.105s) forwards}
.ml-caption-shape{fill:var(--gold);stroke:var(--gold);stroke-width:.7;stroke-dasharray:1;stroke-dashoffset:1;fill-opacity:0;animation:mlLetterReveal .62s cubic-bezier(.2,.8,.2,1) calc(1.55s + var(--order)*.035s) both;transform-box:fill-box;transform-origin:center}
.ml-ornament-shape{fill:var(--white);stroke:var(--white);stroke-width:1;stroke-dasharray:1;stroke-dashoffset:1;fill-opacity:0;animation:mlOrnamentReveal .78s cubic-bezier(.2,.85,.2,1) calc(1.7s + var(--order)*.14s) both;transform-box:fill-box;transform-origin:center}
.ml-flourish-shape{fill:var(--white);stroke:var(--white);stroke-width:1.1;stroke-dasharray:1;stroke-dashoffset:1;fill-opacity:0;animation:mlContourReveal .9s cubic-bezier(.65,0,.25,1) calc(1.95s + var(--order)*.16s) forwards}
.ml-sun-aura{opacity:0;transform-box:fill-box;transform-origin:center;animation:mlAuraBloom 1.4s ease-out .2s forwards, mlAuraBreathe 4.2s ease-in-out 2.2s infinite}
.ml-shine{opacity:0;pointer-events:none;animation:mlShineSweep 5.7s ease-in-out 2.7s infinite}
.ml-shine rect{transform:translateX(-220px);animation:mlShineMove 5.7s ease-in-out 2.7s infinite}
.ml-status{display:flex;align-items:center;flex-direction:column;gap:13px;min-height:42px;text-align:center;animation:mlStatusIn .7s ease-out 1.7s both}
.ml-status-text{font-size:10px;line-height:1.2;letter-spacing:.22em;font-weight:600;text-transform:uppercase;color:rgba(255,255,255,.84);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
.ml-status-dots{display:inline-flex;gap:5px;align-items:center;height:8px}
.ml-status-dots i{display:block;width:4px;height:4px;border-radius:50%;background:var(--gold);opacity:.35;animation:mlDotBeat 1.15s ease-in-out infinite}
.ml-status-dots i:nth-child(2){animation-delay:.16s}
.ml-status-dots i:nth-child(3){animation-delay:.32s}
.ml-progress{width:118px;height:2px;border-radius:10px;background:rgba(255,255,255,.18);overflow:hidden;position:relative}
.ml-progress::after{content:"";position:absolute;inset:0 auto 0 -40%;width:38%;border-radius:inherit;background:linear-gradient(90deg,transparent,var(--gold),#fff4bd,var(--gold),transparent);box-shadow:0 0 10px rgba(254,194,14,.5);animation:mlProgressRun 1.8s cubic-bezier(.55,.05,.35,.95) infinite}
.ml-ripple{position:absolute;left:var(--tap-x,50%);top:var(--tap-y,50%);width:12px;height:12px;border:1px solid rgba(255,255,255,.5);border-radius:50%;pointer-events:none;opacity:0;transform:translate(-50%,-50%) scale(.2)}
.ml-loader.ml-tap .ml-ripple{animation:mlTapRipple .85s ease-out forwards}
.ml-loader.ml-tap .ml-logo-stage{animation:mlTapNudge .42s ease-out}
@keyframes mlContourReveal{0%{stroke-dashoffset:1;fill-opacity:0;filter:brightness(1.6)}62%{stroke-dashoffset:0;fill-opacity:.12}100%{stroke-dashoffset:0;fill-opacity:1;stroke-opacity:0;filter:none}}
@keyframes mlLetterReveal{0%{opacity:0;transform:translateY(7px) scale(.94);filter:blur(2px);stroke-dashoffset:1}65%{opacity:1;stroke-dashoffset:0}100%{opacity:1;transform:translateY(0) scale(1);filter:none;stroke-dashoffset:0;fill-opacity:1;stroke-opacity:0}}
@keyframes mlOrnamentReveal{0%{opacity:0;transform:scaleX(.25) scaleY(.7);stroke-dashoffset:1;fill-opacity:0}75%{opacity:1;stroke-dashoffset:0;fill-opacity:.75}100%{opacity:1;transform:scale(1);stroke-dashoffset:0;fill-opacity:1;stroke-opacity:0}}
@keyframes mlAuraBloom{0%{opacity:0;transform:scale(.55)}100%{opacity:1;transform:scale(1)}}
@keyframes mlAuraBreathe{0%,100%{opacity:.8;transform:scale(1)}50%{opacity:1;transform:scale(1.13)}}
@keyframes mlShineSweep{0%,48%{opacity:0}54%{opacity:.85}67%{opacity:0}100%{opacity:0}}
@keyframes mlShineMove{0%,48%{transform:translateX(-220px)}67%,100%{transform:translateX(950px)}}
@keyframes mlStatusIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@keyframes mlDotBeat{0%,80%,100%{opacity:.3;transform:translateY(0) scale(.8)}40%{opacity:1;transform:translateY(-2px) scale(1.2)}}
@keyframes mlProgressRun{0%{transform:translateX(0)}100%{transform:translateX(390%)}}
@keyframes mlTapRipple{0%{opacity:.75;transform:translate(-50%,-50%) scale(.2)}100%{opacity:0;transform:translate(-50%,-50%) scale(15)}}
@keyframes mlTapNudge{0%,100%{filter:drop-shadow(0 12px 22px rgba(13,29,16,.10))}45%{filter:drop-shadow(0 12px 28px rgba(254,194,14,.24))}}
@media(max-width:480px){.ml-logo-stage{width:min(78vw,390px)}.ml-status-text{font-size:9px;letter-spacing:.19em}}
@media(prefers-reduced-motion:reduce){.ml-loader *,.ml-loader *::before,.ml-loader *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition:none!important}.ml-shape{stroke-dashoffset:0!important;fill-opacity:1!important;stroke-opacity:0!important}.ml-sun-aura{opacity:1!important}}
`

