const LOADER_SCRIPT = `
(function() {
  var loader = document.querySelector('.ml-loader');
  if (!loader) return;
  var resetTimer;
  loader.addEventListener('pointermove', function(e) {
    var rect = loader.getBoundingClientRect();
    var x = ((e.clientX - rect.left) / rect.width - .5) * 2;
    var y = ((e.clientY - rect.top) / rect.height - .5) * 2;
    loader.style.setProperty('--mx', Math.max(-1, Math.min(1, x)).toFixed(3));
    loader.style.setProperty('--my', Math.max(-1, Math.min(1, y)).toFixed(3));
  }, {passive:true});
  loader.addEventListener('pointerleave', function() {
    loader.style.setProperty('--mx',0);
    loader.style.setProperty('--my',0);
  }, {passive:true});
  loader.addEventListener('pointerdown', function(e) {
    var rect = loader.getBoundingClientRect();
    loader.style.setProperty('--tap-x', (e.clientX-rect.left)+'px');
    loader.style.setProperty('--tap-y', (e.clientY-rect.top)+'px');
    loader.classList.remove('ml-tap');
    void loader.offsetWidth;
    loader.classList.add('ml-tap');
    clearTimeout(resetTimer);
    resetTimer = setTimeout(function() { loader.classList.remove('ml-tap'); }, 900);
  }, {passive:true});
})();
`

export function MaatramLoader() {
  const containerRef = useRef<any>(null)
  const styleInjected = useRef(false)

  useEffect(() => {
    if (Platform.OS !== 'web') return

    if (!styleInjected.current) {
      const style = document.createElement('style')
      style.setAttribute('data-maatram-loader', '')
      style.textContent = LOADER_STYLES
      document.head.appendChild(style)
      styleInjected.current = true
    }

    const el = containerRef.current as unknown as HTMLElement
    if (!el) return

    el.innerHTML = LOADER_HTML
    el.className = 'ml-loader'
    el.setAttribute('role', 'status')
    el.setAttribute('aria-live', 'polite')
    el.setAttribute('aria-label', 'Loading the next page')

    const script = document.createElement('script')
    script.textContent = LOADER_SCRIPT
    document.body.appendChild(script)

    return () => {
      script.remove()
    }
  }, [])

  if (Platform.OS === 'web') {
    return <View ref={containerRef} style={{ flex: 1 }} />
  }

  return (
    <View style={{ flex: 1, backgroundColor: '#0D0D0F', alignItems: 'center', justifyContent: 'center' }}>
      <ActivityIndicator size="large" color="#FEC20E" />
    </View>
  )
}
